L["\nExample command for setting numeric values:\n - Set to a value within range: |cFFFFD100/hek set spec %s #|r ( %d-%d)\n"] = "\nExemple de commande pour une valeur numérique :\n - Choisir une valeur dans l’intervalle : |cFFFFD100/hek set spec %s #|r ( %d-%d)\n"
L["\nExample command for setting numeric values:\n - Set to a value within range: |cFFFFD100/hek set spec %s #|r ( %.1f-%.1f)\n"] = "\nExemple de commande pour une valeur numérique :\n - Choisir une valeur dans l’intervalle : |cFFFFD100/hek set spec %s #|r ( %.1f-%.1f)\n"
