L["Use |cFFFFD100/hekili profile name|r to swap profiles. Valid profile names are:"] = "Utilise |cFFFFD100/hekili profile nom|r pour changer de profil. Profils valides :"
L["|cFF00FF00(current)|r"] = "|cFF00FF00(actuel)|r"
