L["Priority set to %s%s|r."] = "Priorité réglée sur %s%s|r."
L["No match found for priority '%s'.\nValid options are:"] = "Aucune priorité ne correspond à '%s'.\nChoix valides :"
L["No specializations: your class has no Hekili Forever pack."] = "Aucune spécialisation : ta classe n’a pas de pack Hekili Forever."
