L["Seconds"] = "Secondes"
L["Max Energy"] = "Énergie max"
L["When checked, this entry waits until the player has enough energy for the ability's full bonus from extra energy."] = "Si coché, cette entrée attend que tu aies assez d’énergie pour le bonus complet de la technique lié à l’énergie en plus."
L["Caption"] = "Légende"
L["Captions are |cFFFF0000very|r short descriptions that can appear on the icon of a recommended ability.\n\nThis can be useful for understanding why an ability was recommended at a particular time.\n\nRequires Captions to be enabled on each display."] = "Les légendes sont des descriptions |cFFFF0000très|r courtes qui peuvent s’afficher sur l’icône d’une technique recommandée.\n\nUtile pour comprendre pourquoi une technique a été recommandée à un moment donné.\n\nNécessite d’activer les légendes dans chaque affichage."
L["Caption text should be 20 characters or less."] = "Le texte de légende doit faire 20 caractères ou moins."
L["Label"] = "Étiquette"
L["Text shown on the recommendation while the Label Condition (if any) holds, e.g. a downranking note."] = "Texte affiché sur la recommandation tant que la condition d’étiquette (s’il y en a une) est vraie, par ex. une note de rang inférieur."
L["Label Condition"] = "Condition d’étiquette"
L["If entered, the Label shows only while this is true."] = "Si renseignée, l’étiquette ne s’affiche que tant que ceci est vrai."
L["Icon"] = "Icône"
L["A texture file ID or path to show on the recommendation in place of the ability's icon while the Icon Condition (if any) holds. A path is resolved when the list loads; a bare file ID is not checked."] = "Un ID de fichier de texture ou un chemin à afficher sur la recommandation à la place de l’icône de la technique tant que la condition d’icône (s’il y en a une) est vraie. Un chemin est résolu au chargement de la liste ; un ID de fichier seul n’est pas vérifié."
L["Not a texture file; this line's icon is not overridden."] = "Pas un fichier de texture ; l’icône de cette ligne n’est pas remplacée."
L["Icon Condition"] = "Condition d’icône"
L["If entered, the Icon shows only while this is true."] = "Si renseignée, l’icône ne s’affiche que tant que ceci est vrai."
L["Condition"] = "Condition"
L["This allows you to provide text that explains this entry, which will show when you Pause and mouseover the ability to see why this entry was recommended."] = "Te permet d’ajouter un texte qui explique cette entrée ; il s’affiche quand tu mets en pause et survoles la technique pour voir pourquoi cette entrée a été recommandée."
L["Variable Name"] = "Nom de la variable"
